list_shipping_rules.code:
final response = await client.shippingRules.listShippingRules(
  queryParams: {
    'zone_id': 5,
    'method': 'flat_rate',
    'handling_cost': 'without_handling',
    'sort': 'name',
    'order': 'asc',
  },
);
final result = response.map as Map;
for (final shippingRule in result['shipping_rules'] as List) {
  print('${(shippingRule as Map)['id']} ${shippingRule['name']}');
}
final pagination = result['pagination'] as Map;
print('${pagination['total']} ${pagination['has_next']}');

count_shipping_rules.code:
